def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None
        # Convert in chunks to avoid Python's limit on decimal string length.
        value = 0
        for i in range(0, len(token), 9):
            chunk = token[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if verb == "undo" and len(parts) == 1:
            if not history:
                rejected.append(index)
                continue

            entry = history.pop()
            kind = entry[0]
            if kind == "open":
                del balances[entry[1]]
                frozen.discard(entry[1])
            elif kind == "deposit":
                balances[entry[1]] -= entry[2]
            elif kind == "withdraw":
                balances[entry[1]] += entry[2]
            elif kind == "transfer":
                balances[entry[1]] += entry[3]
                balances[entry[2]] -= entry[3]
            elif kind == "freeze":
                frozen.remove(entry[1])
            else:
                frozen.add(entry[1])

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            name = parts[1]
            n = amount(parts[2])

            if n is None:
                rejected.append(index)
            elif verb == "open":
                if name in balances:
                    rejected.append(index)
                else:
                    balances[name] = n
                    history.append(("open", name))
            elif verb == "deposit":
                if n == 0 or name not in balances:
                    rejected.append(index)
                else:
                    balances[name] += n
                    history.append(("deposit", name, n))
            else:
                if (n == 0 or name not in balances or name in frozen
                        or balances[name] < n):
                    rejected.append(index)
                else:
                    balances[name] -= n
                    history.append(("withdraw", name, n))

        elif verb == "transfer" and len(parts) == 4:
            source, destination = parts[1], parts[2]
            n = amount(parts[3])
            if (n is None or n == 0 or source == destination
                    or source not in balances or destination not in balances
                    or source in frozen or balances[source] < n):
                rejected.append(index)
            else:
                balances[source] -= n
                balances[destination] += n
                history.append(("transfer", source, destination, n))

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            name = parts[1]
            if verb == "freeze":
                if name not in balances or name in frozen:
                    rejected.append(index)
                else:
                    frozen.add(name)
                    history.append(("freeze", name))
            else:
                if name not in balances or name not in frozen:
                    rejected.append(index)
                else:
                    frozen.remove(name)
                    history.append(("unfreeze", name))
        else:
            rejected.append(index)

    return balances, rejected
